`timescale 1ns/1ps
module tb_completion_snmp_extended;
reg clk=0;always #5 clk=~clk;reg rst=1,req=0;reg [10:0] len=0;reg [4095:0] bytes=0;
wire busy,done,valid,error,snap;wire [7:0] code;wire [10:0] rlen;wire [4095:0] response;wire [31:0] snaps;
reg [799:0] mib=0;integer errors=0,cases=0,t,j;
afdx_snmp_extended dut(.clk(clk),.rst(rst),.request_valid(req),.request_length(len),.request_bytes(bytes),
.community_length(6'd11),.community_bytes({168'd0,88'h747365742d746867696c66}),.mib_values(mib),.busy(busy),.done(done),.response_valid(valid),.error(error),.error_code(code),.response_length(rlen),.response_bytes(response),.snapshot_event(snap),.snapshot_count(snaps));
task query;input [4095:0] b;input integer n;input expect_reject;begin
 @(negedge clk);bytes=b;len=n;req=1;@(negedge clk);req=0;t=0;
 while(!done&&t<6000)begin @(negedge clk);t=t+1;end
 if(!done||valid===expect_reject||error!==expect_reject)begin errors=errors+1;$display("FAIL extended SNMP case=%0d code=%0d timeout=%0d",cases,code,t);end
 $write("EXT_RESPONSE case=%0d reject=%0d hex=",cases,error);
 for(j=0;j<rlen;j=j+1)$write("%02x",response[j*8+:8]);$display("");cases=cases+1;
 repeat(2)@(negedge clk);
end endtask
initial begin
mib[0*32+:32]=32'h00060a01;
mib[1*32+:32]=32'h00000001;
mib[2*32+:32]=32'h87654321;
mib[3*32+:32]=32'h00000007;
mib[4*32+:32]=32'h00000003;
mib[5*32+:32]=32'h00000064;
mib[6*32+:32]=32'h00000065;
mib[7*32+:32]=32'h00000066;
mib[8*32+:32]=32'h00000067;
mib[9*32+:32]=32'h00000068;
mib[10*32+:32]=32'h00000069;
mib[11*32+:32]=32'h0000006a;
mib[12*32+:32]=32'h0000006b;
mib[13*32+:32]=32'h0000006c;
mib[14*32+:32]=32'h0000006d;
mib[15*32+:32]=32'h0000006e;
mib[16*32+:32]=32'h0000006f;
mib[17*32+:32]=32'h00000070;
mib[18*32+:32]=32'h00000071;
mib[19*32+:32]=32'h00000072;
mib[20*32+:32]=32'h00000073;
mib[21*32+:32]=32'h00000074;
mib[22*32+:32]=32'h00000075;
mib[23*32+:32]=32'h00000076;
mib[24*32+:32]=32'h00000077;
repeat(4)@(negedge clk);rst=0;
query(4096'h000501010159fd81010401062b0b060f3011300001020001027fff02021da0747365742d746867696c660b040101022f30,49,0);
query(4096',312,0);
query(4096'h00300001020001020101020ba0747365742d746867696c660b040101021d30,31,0);
query(4096'h0005013788030607300005010201062b05060930000500010605301b3000010200010201010226a0747365742d746867696c660b040101023830,58,0);
query(4096'h000501378803060730000519010159fd81010401062b0b060f3000050004010159fd81010401062b0c061030000500010159fd81010401062b0b060f300005010159fd81010401062b0a060e300005010201062b05060930000500010605305f30000102000102ff01026aa1747365742d746867696c660b040101027c30,126,0);
query(4096'h00055afd81010401062b08060c300005008081010401062b08060c3000057fff010401062b07060b30293000010200010201010234a1747365742d746867696c660b040101024630,72,0);
query(4096',377,0);
query(4096'h63010204010159fd81010401062b0b06103012300001020001020101021da3747365742d746867696c660b040101022f30,49,0);
query(4096'h000501010159fd81010401062b0b060f3011300001020001020101021ca0726568746f05040101022830,42,1);
query(4096'h0501010159fd81010401062b0b060f3011300001020001027fff02021da0747365742d746867696c660b040101022f30,48,1);
query(4096'h000501010159fd81010401062b0b060f3011300001020001027fff02021da0747365742d746867696c660b040101028030,49,1);
$display("EXT_SNMP_CASES=%0d SNAPSHOTS=%0d ERRORS=%0d",cases,snaps,errors);
if(errors==0)$display("TB_COMPLETION_SNMP_EXTENDED_PASS");else $display("TB_COMPLETION_SNMP_EXTENDED_FAIL");$finish;
end
initial begin #1000000;$display("EXT_SNMP_TIMEOUT");$finish;end
endmodule
